import sys
import time

def precompute_V():
    V = {_sage_const_1 }
    for s in range(_sage_const_40 ):
        fs = (_sage_const_10  * _sage_const_16 **s + _sage_const_16  * _sage_const_4 **s + _sage_const_10 ) // _sage_const_9 
        for i in range(_sage_const_160 ):
            val = fs * _sage_const_4 **i
            V.add(val)
    return sorted(list(V))

all_V = precompute_V()

# Pool of small primes = 3 mod 4
primes_pool = [_sage_const_3 , _sage_const_7 , _sage_const_11 , _sage_const_19 , _sage_const_23 , _sage_const_31 , _sage_const_43 , _sage_const_47 , _sage_const_59 , _sage_const_67 , _sage_const_71 , _sage_const_79 , _sage_const_83 , _sage_const_103 , _sage_const_107 , _sage_const_127 ]

N_max = _sage_const_5  * _sage_const_10 **_sage_const_17 
limit = N_max * N_max
V_target = [v for v in all_V if v < limit]
print(f"V_target size for 5 * 10^17: {len(V_target)}")

selected_primes = []
selected_residues = {}
uncovered = list(V_target)

# Greedily pick 12 primes
num_primes = _sage_const_12 
for step in range(num_primes):
    best_p = None
    best_r = None
    best_cov = -_sage_const_1 
    
    for p in primes_pool:
        if p in selected_primes:
            continue
        cov_for_r = [_sage_const_0 ] * p
        for v in uncovered:
            v_mod = v % p
            if v_mod == _sage_const_0 :
                cov_for_r[_sage_const_0 ] += _sage_const_1 
            elif pow(v_mod, (p-_sage_const_1 )//_sage_const_2 , p) == _sage_const_1 :
                for r in range(_sage_const_1 , p):
                    if (r*r) % p == v_mod:
                        cov_for_r[r] += _sage_const_1 
                        cov_for_r[p-r] += _sage_const_1 
                        break
        max_cov = max(cov_for_r)
        best_r_for_p = cov_for_r.index(max_cov)
        if max_cov > best_cov:
            best_cov = max_cov
            best_p = p
            best_r = best_r_for_p
            
    if best_cov <= _sage_const_0 :
        break
        
    selected_primes.append(best_p)
    selected_residues[best_p] = best_r
    new_uncovered = []
