    for v in V_actual:
        diff = N2 - v
        found_p = None
        for p in selected_primes:
            if diff % p == _sage_const_0  and diff % (p*p) != _sage_const_0 :
                found_p = p
                break
        if found_p is None:
            # check small primes up to 1000
            for p in prime_range(_sage_const_3 , _sage_const_1000 ):
                if p % _sage_const_4  == _sage_const_3 :
                    if diff % p == _sage_const_0  and diff % (p*p) != _sage_const_0 :
                        found_p = int(p)
                        break
        if found_p is None:
            factors = factor(diff)
            for p, exp in factors:
                if p % _sage_const_4  == _sage_const_3  and exp % _sage_const_2  != _sage_const_0 :
                    found_p = int(p)
                    break
        if found_p is not None:
            blocking_primes[v] = found_p
        else:
            all_blocked = False
            break
            
    if all_blocked:
        print(f"\nSUCCESS! Found counterexample N = {N} (k = {k}) in {time.time() - start_time:.2f}s")
